-- Seed for plan_sessions — generated from the WEEKS array in index.html.
-- Safe to re-run: on conflict it refreshes the plan text but leaves session_date alone,
-- so any reschedules you've already made survive a re-seed.
-- 84 sessions, 12 weeks, block starts 2026-07-27.

on conflict (week, day) do update set
  title       = excluded.title,
  targets     = excluded.targets,
  detail      = excluded.detail,
  exercises   = excluded.exercises,
  phase       = excluded.phase,
  week_km     = excluded.week_km,
  week_headline = excluded.week_headline;
